(() => {
  const parseBRL = (v) => {
    if (!v) return 0;
    let s = v.toString().trim().replace(/[^\d,.-]/g, '');
    if (s.includes(',') && s.split(',').length === 2) {
      s = s.replace(/\./g, '').replace(',', '.');
    }
    return parseFloat(s) || 0;
  };

  const especiais = ['zero','um','dois','três','quatro','cinco','seis','sete','oito','nove','dez',
    'onze','doze','treze','catorze','quinze','dezesseis','dezessete','dezoito','dezenove'];
  const dezenas = ['','','vinte','trinta','quarenta','cinquenta','sessenta','setenta','oitenta','noventa'];
  const centenas = ['','cento','duzentos','trezentos','quatrocentos','quinhentos','seiscentos','setecentos','oitocentos','novecentos'];

  const trescasas = (n) => {
    if (n === 0) return '';
    if (n === 100) return 'cem';
    const c = Math.floor(n / 100);
    const resto = n % 100;
    const partes = [];
    if (c > 0) partes.push(centenas[c]);
    if (resto > 0) {
      if (resto < 20) partes.push(especiais[resto]);
      else {
        const d = Math.floor(resto / 10);
        const u = resto % 10;
        partes.push(u > 0 ? `${dezenas[d]} e ${especiais[u]}` : dezenas[d]);
      }
    }
    return partes.join(' e ');
  };

  const numeroExtenso = (valorNumerico) => {
    const escalas = [
      { divisor: 1000000000, singular: 'bilhão', plural: 'bilhões' },
      { divisor: 1000000, singular: 'milhão', plural: 'milhões' },
      { divisor: 1000, singular: 'mil', plural: 'mil' },
      { divisor: 1, singular: '', plural: '' }
    ];
    if (valorNumerico === 0) return 'zero';
    let resto = Math.floor(valorNumerico);
    const grupos = [];
    for (const escala of escalas) {
      const qtd = Math.floor(resto / escala.divisor);
      if (qtd > 0) {
        const texto = trescasas(qtd);
        grupos.push(escala.divisor === 1 ? texto : `${texto} ${qtd === 1 ? escala.singular : escala.plural}`);
        resto -= qtd * escala.divisor;
      }
    }
    if (grupos.length === 1) return grupos[0];
    return grupos.slice(0, -1).join(', ') + ' e ' + grupos[grupos.length - 1];
  };

  const formatarExtenso = (valor) => {
    const inteiro = Math.floor(valor);
    const centavos = Math.round((valor - inteiro) * 100);
    const textoReais = `${numeroExtenso(inteiro)} ${inteiro === 1 ? 'real' : 'reais'}`;
    const textoCentavos = centavos > 0
      ? ` e ${numeroExtenso(centavos)} ${centavos === 1 ? 'centavo' : 'centavos'}`
      : '';
    return `${textoReais}${textoCentavos}`;
  };

  const raw = $('Extrair Dados Defesa Administrativa').item.json.output.valores_debitos_detalhados || '';
  const valores = raw.split(';').map(v => v.trim()).filter(v => v.length > 0).map(parseBRL);
  const total = valores.reduce((acc, v) => acc + v, 0);

  const valorFormatado = total.toLocaleString('pt-BR', { minimumFractionDigits: 2 });
  const extenso = formatarExtenso(total);

  return `R$ ${valorFormatado} (${extenso})`;
})()
}}

