// Normaliza: remove markdown, acentos e colapsa espaços -> comparação robusta
const normalize = (str) =>
  (str || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")   // remove acentos
    .replace(/[*_#>`|]/g, " ")         // remove marcações markdown
    .replace(/\s+/g, " ")              // colapsa espaços/quebras
    .toUpperCase()
    .trim();

function detectarPaginas(pages) {
  let paginaDespacho = null;
  let paginaDetalhamento = null;

  pages.forEach((page, i) => {
    const text = normalize(page?.markdown);
    const pageNumber = (typeof page?.index === "number" ? page.index : i) + 1;

    // === DESPACHO DECISÓRIO (CORPO REAL) ===
    const hasTituloDespacho = text.includes("DESPACHO DECISORIO");

    const hasEstruturaNumerada =
      /1\s*[-–]\s*SUJEITO PASSIVO/.test(text) ||
      /2\s*[-–]\s*IDENTIFICACAO/.test(text) ||
      /3\s*[-–]\s*FUNDAMENTACAO/.test(text);

    // Evita página de ciência / aviso da caixa postal
    const isAvisoCiencia =
      (text.includes("CIENTIFICADO DO DESPACHO DECISORIO") ||
        text.includes("MENSAGEM ENVIADA PARA CAIXA POSTAL")) &&
      !hasEstruturaNumerada;

    if (
      paginaDespacho === null &&
      hasTituloDespacho &&
      hasEstruturaNumerada &&
      !isAvisoCiencia
    ) {
      paginaDespacho = pageNumber;
    }

    // === DETALHAMENTO DA COMPENSAÇÃO ===
    const hasDetalhamento =
      text.includes("DETALHAMENTO DA COMPENSACAO") &&
      text.includes("VALORES DEVEDORES");

    if (paginaDetalhamento === null && hasDetalhamento) {
      paginaDetalhamento = pageNumber;
    }
  });

  return {
    // Fallback padrão (se não encontrou nada)
    pagina_despacho_decisorio: paginaDespacho ?? 2,
    pagina_detalhamento_compensacao: paginaDetalhamento ?? 3,
  };
}

return $input.all().map((item) => {
  const pages = Array.isArray(item.json.pages) ? item.json.pages : [];

  return {
    json: {
      ...detectarPaginas(pages),
      ...item.json,
    },
    binary: item.binary,
  };
});
